return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Joan Plugin bilaketara','Activate %s' => 'Aktibatu %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> <strong>%2$s</strong> instalatu eta aktibatu behar da. <a href="%4$s">%3$s</a>','Enter your code here' => 'Sartu zure kodea hemen','Add %s' => 'Gehitu %s','Remove' => 'Kendu','Order number and receipt will be sent to this email address.' => 'Eskaera zenbakia eta ordainagiria helbide elektroniko honetara bidaliko dira.','Apartment, unit, building, floor, etc.' => 'Apartamentua, unitatea, eraikina, solairua, etab.','Shipping phone' => 'Bidalketa telefonoa','Only used for shipping-related questions.' => 'Bidalketarekin lotutako galderetarako soilik erabiltzen da.','Single step' => 'Urrats bakarra','Click to go to the order summary' => 'Egin klik eskaeraren laburpenera joateko','Cart total:' => 'Saskia guztira:','Proceed to %s' => 'Joan %s-era','Proceed to contact' => 'Jarraitu harremanetan','Proceed to shipping' => 'Bidalketarekin jarraitu','Proceed to billing' => 'Jarraitu fakturaziora','Proceed to payment' => 'Ordainketarekin jarraitu','Shipping method' => 'Bidalketa metodoa','Additional notes' => 'Ohar osagarriak','Payment method' => 'Ordainketa modua','Step %1$s of %2$s' => '%1$s/%2$s urratsa','Change: %s' => 'Aldaketa: %s','Not selected yet.' => 'Oraindik hautatu gabe.','Same as shipping address' => 'Bidalketa helbidearen berdina','Same as billing address' => 'Fakturazio helbidearen berdina','Order summary' => 'Eskaeraren laburpena','Edit cart' => 'Editatu saskia','Did you mean %s?' => '%s esan nahi al zenuen?','Change email address to: {suggestion-value}' => 'Aldatu helbide elektroniko honetara: {suggestion-value}','This is a required field.' => 'Hau nahitaezko eremua da.','This is not a valid email address.' => 'Hau ez da baliozko helbide elektronikoa.','This field does not match the related field value.' => 'Eremu hau ez dator bat erlazionatutako eremuaren balioarekin.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF zenbakia ez da baliozkoa.','The CNPJ number "{cnpj_number}" is invalid.' => '&quot;{cnpj_number}&quot; CNPJ zenbakia ez da baliozkoa.','(Required)' => '(Derrigorrezkoa)','Checkout Header - Desktop' => 'Checkout goiburua - Mahaigaina','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Bistaratu widget-ak ordaintzeko goiburuan pantaila handietarako. Pluginaren ordainketa-goiburua erabiltzen baduzu soilik bistaratzen da.','Checkout Header - Mobile' => 'Checkout goiburua - Mugikorra','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Erakutsi widget-ak ordainketa-goiburuaren azpian gailu mugikorretarako. Pluginaren ordainketa-goiburua erabiltzen baduzu soilik bistaratzen da.','Checkout Sidebar' => 'Ordainketa alboko barra','Display widgets on the checkout sidebar after the order summary.' => 'Erakutsi widget-ak ordainketa alboko barran eskaeraren laburpenaren ondoren.','Checkout Order Summary' => 'Ordainketa eskaeraren laburpena','Display widgets inside the order summary at the checkout page.' => 'Erakutsi widget-ak eskaeraren laburpenaren barruan ordainketa-orrian.','Checkout Below Place Order' => 'Egin eskaeraren azpian','Display widgets below the place order button at the checkout page.' => 'Erakutsi widget-ak eskaera egiteko botoiaren azpian ordainketa-orrian.','Checkout Footer' => 'Ordainketa orria','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Bistaratu widget-ak ordainketa-oinean. Pluginaren ordainketa-oina erabiltzen baduzu bakarrik bistaratzen da.','Classic' => 'Klasikoa','Boxed' => 'Kutxatuta','Split' => 'Zatitu','Minimalist' => 'Minimalista','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout eta Delivery Date pluginak CodeRockz-ek','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>CodeRockz-ek WooCommercerako Delivery &amp; Pickup Date Time pluginak (doakoak eta PRO) erabiltzen ari zarela detektatu dugu. Plugin hauekin integrazioa Fluid Checkout PROra eraman da.</p>','Upgrade to PRO' => 'Berritu PRO-ra','Fluid Checkout database updated successfully' => 'Fluid Checkout datu-basea behar bezala eguneratu da','The database changes where applied successfully.' => 'Datu-basea ondo aplikatzen denean aldatzen da.','Dismiss' => 'Baztertu','Fluid Checkout database update' => 'Fluid Checkout datu-basearen eguneratzea','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Datu-basean aldaketa batzuk egin behar dira. Eguneratze guztietan bezala, <strong>zure webgunearen babeskopia osoa egitea gomendatzen dizugu jarraitu aurretik</strong> .','Update database' => 'Eguneratu datu-basea','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ez da bateragarria Divi Builder checkout diseinuarekin','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout-ek WooCommerce kode laburrean oinarritutako ordainketa inprimaki klasikoa behar du funtzionatzeko. Divi Builder-a ordainketa-orriaren itxura pertsonalizatzeko erabiltzean, kode labur klasikoak Divi Builder-eko widget pertsonalizatuekin ordezkatzen dira ordainketa-orriaren zati bakoitzeko. Widget pertsonalizatu hauek ez dira bateragarriak Fluid Checkout-ekin.</p><p> Mesedez, editatu ordainketa orria Divi Builder widget-ak ordezkatuz <code>[woocommerce_checkout]</code> kode laburra duen testu widget batekin.</p>','Edit the checkout page' => 'Editatu ordainketa orria','Read the documentation.' => 'Irakurri dokumentazioa.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanized PRO urrats anitzeko ordainketa eginbidea desgaitu egin behar da Fluid Checkout erabiltzean','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout erabiltzean, Germanized PRO pluginaren urrats anitzeko eginbidea ez da beharrezkoa izango eta <strong>akats larriak sor ditzake eskaera berriak prozesatzen diren bitartean</strong> . Mesedez, desgaitu Germanized PRO urrats anitzeko ordainketa eginbidea pluginaren ezarpenetan.','Go to Germanized settings' => 'Joan germanizatutako ezarpenetara','Thanks for choosing Fluid Checkout!' => 'Eskerrik asko Fluid Checkout aukeratzeagatik!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Plugin-a erabiltzen ari zara pixka bat. Nola gustatzen zaizu orain arte?<br> Mesedez, eman iezaguzu balorazio azkar bat, iritzi guztiak eskertzen ditugu eta plugina hobetzen jarraitzera animatzen gaitu :)','Rate the plugin' => 'Baloratu plugina','I need help!' => 'Laguntza behar dut!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Baliteke Quadlayers-en WooCommerce Checkout Manager-en eginbide batzuk espero bezala ez funtzionatzea Fluid Checkout-ekin erabiltzean. Irakurri <a href="%s">gure dokumentazioa</a> informazio gehiago eta irtenbide alternatiboak lortzeko.','Read documentation' => 'Irakurri dokumentazioa','Don\'t show this again' => 'Ez erakutsi hau berriro','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Diseinu txantiloi gehiago','Optimized cart page' => 'Orga orri optimizatua','Optimized order received / thank you page' => 'Jasotako eskaera optimizatua / eskerrik asko orria','Edit cart contents at checkout page' => 'Editatu saskiaren edukia ordainketa orrian','Account matching / user matching' => 'Kontua bat etortzea / erabiltzailea bat etortzea','Trust symbols on the cart and thank you pages' => 'Konfiantza-sinboloak saskian eta eskerrik asko orrialdeetan','More positions for the coupon code on the checkout page' => 'Kupoi kodearen posizio gehiago ordainketa orrian','International phone numbers' => 'Nazioarteko telefono zenbakiak','Gift messages and packing slips' => 'Opari mezuak eta ontziratze-agiriak','Local pickup and in-store collection' => 'Bertako bilketa eta denda barruko bilketa','EU-VAT Assistant' => 'EB-BEZ laguntzailea','I already have it – Hide this offer' => 'Dagoeneko daukat - Ezkutatu eskaintza hau','Activated' => 'Aktibatuta','Address book' => 'Helbide liburua','Select an image' => 'Hautatu irudi bat','Cart layout' => 'Saskiaren diseinua','Cart optimizations' => 'Saskiaren optimizazioak','Enable cart page optimizations' => 'Gaitu saskiaren orriaren optimizazioak','Header and footer template' => 'Goiburua eta oinaren txantiloia','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Distrakziorik gabeko orriaren goiburua eta oina erabili edo unean aktibo dagoen gaiaren goiburua eta oina mantendu behar den kontrolatzen du.','Distraction free header and footer' => 'Distrakziorik gabeko goiburua eta oina','Theme\'s header and footer' => 'Gaiaren goiburua eta oina','Cart elements' => 'Orga-elementuak','Make the order summary stay visible on the cart page while scrolling' => 'Egin eskaeraren laburpena ikusgai saskiaren orrian korritzen duzun bitartean','Coupon codes' => 'Kupoi kodeak','Hidden' => 'Ezkutuan','Before the cart items section' => 'Saskia elementuen atalaren aurretik','Inside the cart items section' => 'Saskiaren elementuen atalaren barruan','After the cart items section' => 'Saskia elementuen atalaren ondoren','Before the shipping section' => 'Bidalketa atalaren aurretik','After the shipping section' => 'Bidalketa atalaren ondoren','Before the order summary' => 'Eskaeraren laburpena baino lehen','Inside the order summary' => 'Eskaeraren laburpenaren barruan','Before the order totals' => 'Aginduak guztizkoak baino lehen','After the order totals' => 'Aginduaren guztizkoen ondoren','After the order summary' => 'Aginduaren laburpena egin ondoren','Shipping' => 'Bidalketa','Select position where to display the shipping costs and calculator on the cart page.' => 'Hautatu saskiaren orrian bidalketa-gastuak eta kalkulagailua bistaratzeko posizioa.','Display as a cart section' => 'Erakutsi saskia atal gisa','Cross-sells' => 'Salmenta gurutzatuak','Select position where to display the cross-sells section on the cart page.' => 'Hautatu saskiaren orrialdeko salmenta gurutzatuak atala bistaratzeko posizioa.','Before the cart actions' => 'Orga ekintzen aurretik','After the cart actions' => 'Orga ekintzen ostean','Layout of cross-sell items on the cart page.' => 'Salmenta gurutzatutako elementuen diseinua saskiaren orrian.','Optimized horizontal cross-sells layout' => 'Salmenta gurutzatuen diseinu horizontal optimizatua','Theme\'s cross-sells layout' => 'Gaiaren salmenta gurutzatuen diseinua','Number of cross-sell items to display on the cart page' => 'Saskiaren orrian bistaratu beharreko salmenta gurutzatutako elementu kopurua','Add widget areas to the cart page' => 'Gehitu widget-eremuak saskiaren orrira','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Widget-eremu hauek saskiaren orrian konfiantza-ikurrak eta konfiantza-txapak gehitzeko erabiltzen dira.','Checkout' => 'Ordainketa','Checkout layout' => 'Ordainketa diseinua','Design template' => 'Diseinu txantiloia','Dark mode' => 'Modu iluna','Enable dark mode' => 'Gaitu modu iluna','Logo image' => 'Logotipoaren irudia','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Aukeratu ordainketa-orriaren goiburuan bistaratzeko irudi bat. Distrakziorik gabeko goiburua eta oina erabiltzean soilik aplikatzen da.','Header background color' => 'Goiburuko atzeko planoaren kolorea','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Aukeratu atzeko planoko kolorea ordainketa-orriaren goibururako. Distrakziorik gabeko goiburua eta oina erabiltzean soilik aplikatzen da.','HTML color value. ie: #f3f3f3' => 'HTML kolore-balioa. hau da: #f3f3f3','Page background color' => 'Orriaren atzeko planoaren kolorea','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Aukeratu atzeko planoko kolorea ordainketa-orrirako. Kolorea <em>gorputz-</em> elementuari aplikatzen zaio.','Footer background color' => 'Oinaren atzeko planoaren kolorea','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Aukeratu atzeko planoko kolorea ordainketa-orriaren oinerako. Distrakziorik gabeko goiburua eta oina erabiltzean soilik aplikatzen da.','Progress bar' => 'Aurrerapen-barra','Display the checkout progress bar when using multi-step checkout layout' => 'Bistaratu ordainketaren aurrerapen-barra urrats anitzeko ordainketa-diseinua erabiltzen duzunean','Make the checkout progress bar stay visible while scrolling' => 'Egin ordainketaren aurrerapen-barra ikusgai egon dadin korritzen duzun bitartean','Express checkout' => 'Ordainketa express','Enable the express checkout section' => 'Gaitu ordainketa zehatza atala','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Ordainketa-pasabide onargarriek eginbide hau gaituta dutenean, ordainketa zehatzeko atala bistaratzen du ordainketetan.','Display express checkout buttons in one line for larger screens' => 'Bistaratu ordaintzeko botoiak lerro batean pantaila handiagoetarako','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ez ikusi ordaintzeko beharrezkoak diren eremu gehigarriak ordainketa espresuko ordainketa-pasabide bateragarri batekin ordaintzerakoan','Make the order summary stay visible while scrolling' => 'Egin eskaeraren laburpena ikusgai egon korritzen duzun bitartean','Choose a background color for the order summary section.' => 'Aukeratu atzeko planoko kolorea eskaeraren laburpenaren atalerako.','Highlight the order totals row in the order summary table' => 'Nabarmendu eskaeraren guztizkoen errenkada eskaeraren laburpen-taulan','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Erabilgarriena eskaeraren laburpenaren atalak atzeko planoko kolore nabarmenik ez duenean. Saskia, Jasotako eskaera eta Ikusi eskaera orrietan ere aplika daiteke Fluid Checkout PRO erabiltzen duzunean.','Action link on the order summary at checkout.' => 'Ekintza-esteka eskaeraren laburpenean ordaintzean.','Edit cart link' => 'Editatu saskiaren esteka','Cart items count' => 'Saskiko elementuak zenbatzen dira','Link to shop page' => 'Esteka denda orrira','Cart items' => 'Saskia elementuak','Hide cart items errors at the checkout page' => 'Ezkutatu saskiko elementuen erroreak ordainketa-orrian','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Ez erakutsi saskiko elementuen erroreen mezua ordainketa-orriaren goialdean. Erosketa osatzeko ordainketa-inprimakia bidaltzean, errore-mezu hauek beti agertuko dira.','Place order' => 'Egin eskaera','Define the position to display "Place order" and terms checkbox section.' => 'Definitu &quot;Egin eskaera&quot; eta baldintzak kontrol-laukiaren atala bistaratzeko posizioa.','Some options might not be compatible with some plugins and themes.' => 'Baliteke aukera batzuk plugin eta gai batzuekin bateragarriak ez izatea.','Below the payment section' => 'Ordainketa atalaren azpian','Below the order summary' => 'Eskaeraren laburpenaren azpian','Both below the payment section and the order summary' => 'Ordainketa atalaren azpian eta eskaeraren laburpena','Add widget areas to the checkout page' => 'Gehitu widget eremuak ordainketa-orrian','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Widget-eremu hauek ordainketa-orrian konfiantza-ikurrak eta konfiantzazko bereizgarriak gehitzeko erabiltzen dira.','Display the coupon codes section title' => 'Erakutsi kupoi-kodeen atalaren izenburua','Select position where to display the coupon codes section on the checkout page.' => 'Hautatu ordainketa-orrian kupoi-kodeen atala bistaratzeko posizioa.','Before the checkout steps' => 'Ordainketa urratsen aurretik','As a substep before payment methods' => 'Ordainketa metodoen aurreko azpiurrats gisa','As a substep after payment methods' => 'Ordainketa-metodoen ondorengo azpi-urrats gisa','Default button style' => 'Botoiaren estilo lehenetsia','"Add" link button' => '&quot;Gehitu&quot; esteka botoia','Checkout fields' => 'Ordainketa eremuak','Optional fields' => 'Aukerako eremuak','Hide optional fields behind a link button' => 'Ezkutatu aukerako eremuak esteka-botoi baten atzean','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Aukera hau markatuta mantentzea gomendatzen da sarrera-eremu irekien kopurua murrizteko, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">irakurri ikerketa</a> .','Do not hide "Address line 2" fields behind a link button' => 'Ez ezkutatu &quot;Helbidearen 2. lerroa&quot; eremuak esteka-botoi baten atzean','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Gomendatzen da bezero gehienek &quot;Helbidea 2. lerroa&quot; eremua benetan behar dutenean edo bidalketa-helbide egokia lortzea funtsezkoa denean (adibidez, janaria eta beste produktu galkorrak entregatzen badituzu).','Billing address' => 'Fakturazio helbidea','Select position where to display the billing address section on the checkout page.' => 'Hautatu ordainketa-orrian fakturazio helbidearen atala bistaratzeko posizioa.','As a step before shipping' => 'Bidalketa aurreko urrats gisa','As a sub-step before the shipping address section' => 'Bidalketa helbidearen atalaren aurreko azpi-urrats gisa','As a sub-step after the shipping address section' => 'Bidalketa helbidearen atalaren ondorengo azpi-urrats gisa','As a step after shipping' => 'Bidalketa ondorengo urrats gisa','As a sub-step before the payment section' => 'Ordainketa atalaren aurreko azpi-urrats gisa','Force billing and shipping addresses to the same (single section)' => 'Behartu fakturazio eta bidalketa helbideak berdinera (atal bakarra)','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;Bidalketa/fakturazio-helbidearen berdina&quot; kontrol-laukia lehenespenez markatuta dago','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => '&quot;Bidalketa-helbidearen berdina&quot; kontrol-laukia lehenespenez markatuta dagoen moduan hasiko da bidalketa-helbidearen atala lehenik bistaratzen denean.<br> &quot;Fakturazio-helbidearen berdina&quot; kontrol-laukia lehenespenez markatuta dagoen moduan hasiko da fakturazio-helbidearen atala lehenik bistaratzen denean.<br> Aukera hau markatuta uztea gomendatzen da ordainketan sarrerako eremu irekien kopurua nabarmen murrizteko, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">irakurri ikerketa</a> .','Highlight the billing address section in the checkout form' => 'Nabarmendu fakturazio helbidearen atala ordainketa egiteko formularioan','Shipping address' => 'Bidalketa helbidea','Highlight the shipping address section in the checkout form' => 'Nabarmendu bidalketa helbidearen atala ordainketa egiteko formularioan','Shipping methods' => 'Bidalketa metodoak','Choose in which position to display the shipping methods section.' => 'Aukeratu bidalketa-metodoen atala zein posiziotan bistaratu.','Before shipping address' => 'Bidalketa helbidea baino lehen','After shipping address' => 'Bidalketa helbidearen ondoren','Local pickup' => 'Tokiko bilketa','Removes shipping address section when a local pickup shipping method is selected.' => 'Bidalketa helbidearen atala kentzen du tokiko bilketa bidalketa metodo bat hautatzen denean.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Bidalketa helbidea bilketa puntuaren kokapenarekin ordezkatzen du tokiko bilketa bidalketa metodo bat hautatzen denean.','Choose which address to save as the shipping address for local pickup orders.' => 'Aukeratu zein helbide gorde nahi duzun tokiko bilketa-eskaeretarako bidalketa-helbide gisa.','Save the selected pickup location' => 'Gorde hautatutako bilketa-lekua','Save same as the billing address' => 'Gorde fakturazio helbidea bezala','Do not save any shipping address' => 'Ez gorde bidalketa-helbiderik','Company name field for shipping address' => 'Enpresaren izenaren eremua bidalketa-helbiderako','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Aldatu ordainketa-inprimakiko bidalketa helbidearen ataleko enpresaren izenaren eremuaren ikusgarritasuna.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Eremua &quot;aukerakoa&quot; gisa ezartzen bada, hau da, ikusgarritasun-egoera lehenetsia, ez da aldaketarik aplikatuko beste plugin-ek behar dituzten aldaketak aplika ditzaten.','Hidden (remove field)' => 'Ezkutatuta (kendu eremua)','Optional' => 'Aukerakoa','Required' => 'Beharrezkoa','Add shipping phone field to the checkout form.' => 'Gehitu bidalketa-telefonoaren eremua ordainketa-inprimakiari.','Choose in which step to display the shipping phone field.' => 'Aukeratu zein urrats bistaratzeko bidalketa-telefonoaren eremua.','Contact step' => 'Harremanetarako urratsa','Billing phone' => 'Fakturazio telefonoa','Add billing phone field to the checkout form.' => 'Gehitu fakturazio telefonoaren eremua ordainketa egiteko formularioan.','Choose in which step to display the billing phone field.' => 'Aukeratu zein urrats bistaratzeko fakturazio telefonoaren eremua.','Show country code beside the flag' => 'Erakutsi herrialde-kodea banderaren ondoan','Show an example of a valid phone number inside phone fields' => 'Erakutsi baliozko telefono-zenbaki baten adibide bat telefono-eremuen barruan','Do not change placeholders' => 'Ez aldatu leku-markak','Show if not defined' => 'Erakutsi definitu ez bada','Always show' => 'Erakutsi beti','Order notes' => 'Ordena oharrak','Define the visibility of the additional order notes field.' => 'Definitu eskaera-ohar osagarrien eremuaren ikusgarritasuna.','Gift options' => 'Opari aukerak','Allow customers to add a gift message and other gift related options to the order.' => 'Eman bezeroei opari-mezu bat eta opariekin lotutako beste aukera batzuk gehitzeko eskaerari.','Display the gift message as part of the order details table instead of a separate section' => 'Bistaratu opari-mezua eskaeraren xehetasunen taularen zati gisa, atal bereizi baten ordez','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Aukera honek eskaeraren berrespen-orrian (eskerrak orria) eta kontu-orrietan, mezu elektronikoetan eta ontziratze-agirian eragiten du.','Account matching' => 'Kontua bat etortzea','Enable the account matching feature' => 'Gaitu kontua lotzeko eginbidea','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Lotu bezero gonbidatuaren eskaerak lehendik duen kontuarekin kontu bat dagoeneko bezeroaren kontaktu-datuekin dagoenean.','Display message when an account exists with the email address provided' => 'Bistaratu mezua emandako helbide elektronikoarekin kontu bat dagoenean','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Kontua sortzeko eremuak jakinarazpen batekin eta saioa hasteko aukerarekin ordezkatzen ditu. Zenbait testuingurutan, baliteke aukera hau desgaituta uztea bezeroen pribatutasuna babesteko.','Dashboard' => 'Aginte-panela','Integrations' => 'Integrazioak','License keys' => 'Lizentzia-gakoak','Visit our website for more information about our plugins and add-ons.' => 'Bisitatu gure webgunea gure pluginei eta gehigarriei buruzko informazio gehiago lortzeko.','Order pay page' => 'Ordainketa eskaera orria','Order pay' => 'Ordainketa agindu','Enable order pay page optimizations' => 'Gaitu eskaera ordaintzeko orrien optimizazioak','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Bezeroaren ordainketa zain dauden eskaeren eskaera-orriaren diseinua aldatzen du.','Add widget areas to the order pay page' => 'Gehitu widget eremuak eskaera ordaintzeko orrian','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Widget-eremu hauek konfiantza-ikurrak eta konfiantzazko bereizgarriak gehitzeko erabiltzen dira eskaera ordaintzeko orrian.','Thank you page & order details layout' => 'Eskerrik asko orriaren eta eskaeraren xehetasunen diseinua','Order details optimizations' => 'Eskaeraren xehetasunen optimizazioak','Enable thank you page and order details optimizations' => 'Gaitu eskerrik asko orria eta eskaeraren xehetasunen optimizazioak','Changes the layout of order details on the thank you page and account pages.' => 'Eskaeraren xehetasunen diseinua aldatzen du esker onen orrian eta kontuaren orrietan.','Enable order details customizations on email notifications' => 'Gaitu eskaeraren xehetasunen pertsonalizazioak posta elektronikoko jakinarazpenetan','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Erakutsi atal berriak eta aldatu posta elektronikoko jakinarazpenetan atalen ordena. Posta elektronikoko jakinarazpenetako eskaeraren xehetasunen estiloak ez dira aldatu.','Thank you page' => 'Eskerrik asko orrialdea','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Aukera hauek eskerrak emateko orrialdeari eragiten diote, jasotako eskaera edo eskaera berrespen orri gisa ere ezagutzen dena.','Order details layout' => 'Eskaeraren xehetasunen diseinua','Display the order details with wide layout on the thank you page' => 'Erakutsi eskaeraren xehetasunak diseinu zabalarekin eskerrak emateko orrian','Add widget areas to the thank you page' => 'Gehitu widget-eremuak eskerrak emateko orrialdean','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Widget-eremu hauek esker on orrialdean konfiantza-ikurrak eta konfiantza-txapak gehitzeko erabiltzen dira.','Order actions' => 'Agindu ekintzak','Choose in which position to display the order actions.' => 'Aukeratu ordenaren ekintzak zein posiziotan bistaratu.','Inside the order overview' => 'Eskaeraren ikuspegi orokorraren barruan','After the order overview' => 'Eskaera orokorraren ondoren','After order sections' => 'Agindu atalen ondoren','Order status' => 'Eskaeraren egoera','Display the order status progress bar' => 'Bistaratu eskaeraren egoeraren aurrerapen-barra','Choose in which position to display the section.' => 'Aukeratu atala zein posiziotan bistaratu.','After the order overview and payment instructions' => 'Eskaeraren ikuspegi orokorra eta ordainketa argibideak ondoren','Before the order items section' => 'Eskaera elementuen atalaren aurretik','Inside the order items section' => 'Eskaera-elementuen atalaren barruan','After the order items section' => 'Eskaera elementuen atalaren ondoren','On the sidebar' => 'Alboko barran','Order downloads' => 'Eska ezazu deskargak','Gift message' => 'Opari mezua','Tools' => 'Tresnak','Troubleshooting' => 'Arazoak konpontzea','Debug options' => 'Arazketa aukerak','Debug mode' => 'Arazte modua','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Arazketa modua erabiltzeak webgunearen errendimenduari eragiten dio. Erabili aukera hau arazoak konpontzen dituzun bitartean.','Load unminified assets' => 'Kargatu gutxitu gabeko aktiboak','Enhanced select fields' => 'Aukeratutako eremu hobetuak','Fix automatic zoom-in on form fields' => 'Konpondu inprimaki-eremuetan zoom automatikoa','Set <code>font-size</code> inside form fields to 16px' => 'Ezarri <code>font-size</code> inprimaki-eremuen barruan 16 px-en','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Ezarpenak','Support' => 'Laguntza','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Bertsio-berritu PRO-ra</a> aukera gehiago desblokeatzeko.','(PRO)' => '(PRO)','(experimental)' => '(esperimentala)','Please verify your phone number.' => 'Egiaztatu telefono-zenbakia.','The Bluehost Plugin' => 'Bluehost plugina','Custom fields' => 'Eremu pertsonalizatuak','Enable custom shipping email field' => 'Gaitu bidalketa elektronikoaren eremu pertsonalizatua','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Gaituta dagoenean, Bluehost pluginaren bidalketa-mezuaren eremua ordaintzeko formularioan gehituko da.','Captcha Pro by BestWebSoft' => 'BestWebSoft-en Captcha Pro','Captcha position' => 'Captcha posizioa','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definitu captcha atala bistaratzeko posizioa. Baliteke posizio batzuk ez funtzionatzea aukeratutako captcha motaren arabera.','Selecting a pickup point is required before proceeding.' => 'Jarraitu aurretik jasotzeko puntu bat hautatzea beharrezkoa da.','Pickup point' => 'Jasotzeko puntua','Pickup point not selected yet.' => 'Jasotze-puntua ez da hautatu oraindik.','Pickup point:' => 'Jasotzeko puntua:','Mailchimp for WooCommerce' => 'Mailchimp WooCommercerako','Subscribe checkbox' => 'Harpidetu kontrol-laukia','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Gainidatzi ordainketa-orriko harpidetza-laukiaren posizioa eta bistaratu beti kontaktuaren urratsean','Before Shipping Address' => 'Bidalketa helbidea baino lehen','(originally "%s")' => '(jatorriz &quot;%s&quot;)','After Shipping Address' => 'Bidalketa helbidearen ondoren','Selecting a collection point is required when shipping with FermoPoint.' => 'Bilketa-puntu bat hautatzea beharrezkoa da FermoPoint-ekin bidaltzeko.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Markatuta badago, erabiltzaileei mezu elektronikoetan akatsen berri ematen die. (Eginbide hau desgaitu egin da, Fluid Checkout-ek eginbidea eskaintzen duelako. Aukera honen aldaketek ez dute eraginik izango)','Enable Mail Check: (disabled feature)' => 'Gaitu posta-egiaztapena: (eginbide desgaituta)','Carrier:' => 'Garraiolaria:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'Erregistratu kontrol-laukiaren posizioa','Move the sign up checkbox to the contact step' => 'Eraman izena emateko kontrol-laukia kontaktuaren urratsera','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Gaituta dagoenean, kontrol-laukia kontaktu-urratsera eramango da Sendinblue pluginaren ezarpenetan zehaztutako bistaratze-kokapenetik independenteki.','Theme Betheme' => 'Betheme gaia','Checkout progress' => 'Ordainketa aurrerapena','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Irte ezazu Betheme-ko ordainketa-urratsen atala ordainketa, saskia eta jasotako eskaera orrietan.','Theme Fennik' => 'Gaia Fennik','Breadcrumbs' => 'Ogi birrindua','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Irte ezazu Fennik gaiaren ogi-mamien atala Fluid Checkout goiburua eta oina erabiltzean.','Theme Go' => 'Gaia Go','My account layout' => 'Nire kontuaren diseinua','Enable wide layout on "My account" page.' => 'Gaitu diseinu zabala &quot;Nire kontua&quot; orrian.','Theme Impreza' => 'Gaia Impreza','Header' => 'Goiburua','Spacing for site header at the checkout page (in pixels)' => 'Orrialdearen goiburuko tartea ordainketa-orrian (pixeletan)','Only applicable when using the Impreza theme header at the checkout page.' => 'Ordainketa orrian Impreza gaiaren goiburua erabiltzean soilik aplikagarria.','Theme Kapee' => 'Gaia Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Irte ezazu Kapee gaiaren ordainketa-urratsen atala ordainketa, saskia eta jasotako eskaera orrietan.','Theme Porto' => 'Gaia Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Irte ezazu ordaintzeko urratsen atala Porto gaiaren ordainketa, gurdi eta eskaera jasotako orrietan.','Theme Pressmart' => 'Gaia Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Irte ezazu ordaintzeko urratsen atala Pressmart gaiaren ordainketa, saskia eta jasotako eskaera orrietan.','Theme The Gem' => 'Gaia Harribitxia','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Irte ezazu The Gem gaiaren ordainketa-urratsen atala Fluid Checkout goiburua eta oina erabiltzean.','Theme Woodmart' => 'Woodmart gaia','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Irte ezazu ordaintzeko urratsen atala Woodmart gaitik Fluid Checkout goiburua eta oina erabiltzen duzunean.','Checkout options' => 'Ordainketa aukerak','Disable the theme checkout options' => 'Desgaitu gaiaren ordainketa aukerak','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Aukerak produktuaren irudia, kantitatearen eremua, kendu botoia eta gaiak gehitutako produktuaren orrirako esteka bistaratzen ditu lehenespenez.','Theme Atomion' => 'Gaia Atomion','Order progress' => 'Eskaeraren aurrerapena','Display order progress from the theme' => 'Erakutsi gaiaren eskaeraren aurrerapena','Display the form field labels visible on the page' => 'Erakutsi orrialdean ikusgai dauden inprimaki-eremuen etiketak','It is recommended to keep this option enabled for a better user experience.' => 'Aukera hau gaituta mantentzea gomendatzen da erabiltzailearen esperientzia hobea izateko.','Theme ZK Nito' => 'Gaia ZK Nito','Add extra fields to the checkout form' => 'Gehitu eremu gehigarriak ordainketa-inprimakiari','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Bidalketa helbide elektronikoa eta bidalketa telefono eremua gehitzen ditu bidalketa helbidearen atalean.','Go to the home page' => 'Joan hasierako orrialdera','Skip to content' => 'Saltatu edukira','Create an account' => 'Sortu kontu bat','Log in to your account' => 'Hasi saioa zure kontuan','Already have an account?' => 'Dagoeneko kontu bat duzu?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s gisa hasi da saioa. <a href="%2$s">Amaitu saioa</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Zure eskaerak %s-ko zenbateko osoa du. Ez da ordainketa gehiago behar.','Close and continue with checkout' => 'Itxi eta jarraitu ordainketarekin','Continue' => 'Jarraitu','Parcel terminal' => 'Paketeen terminala','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Widget hau Fluid Checkout-ekin ordezkatu da.</p><p> Fluid Checkout erabiltzean, ordainketa-orriak jatorrizko WooCommerce shortcode <code>[woocommerce_checkout]</code> erabili behar du behar bezala funtzionatzeko.</p><p> Informazio gehiago lortzeko, bisitatu Fluid Checkout dokumentazioa.</p>','Theme The7' => 'Gaia The7','Additional header sections' => 'Goiburuko atal gehigarriak','Output additional header sections if enabled in the theme settings.' => 'Iretzi goiburuko atal gehigarriak gaiaren ezarpenetan gaituta badago.','More information' => 'Informazio gehiago','Pick a Locker' => 'Aukeratu armairu bat','Page template' => 'Orrialdearen txantiloia','Use `Order confirmation` page template for block-based themes' => 'Erabili `Eskaera berresteko` orriaren txantiloia blokeetan oinarritutako gaietarako','Only applies when using a block-based theme.' => 'Blokeetan oinarritutako gai bat erabiltzean bakarrik aplikatzen da.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe atebidea','Payment form' => 'Ordainketa-formularioa','Apply styles to the Stripe payment form fields' => 'Aplikatu estiloak Stripe ordainketa-formularioaren eremuetan','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Gaituta dagoenean, Fluid Checkout-ek pluginarekin bateragarritasunerako optimizatutako estiloak aplikatuko ditu. Baliteke hau desgaitu nahi izatea Stripe ordainketa-formularioaren eremuetarako estilo pertsonalizatuak erabiltzen ari bazara.','Theme Nyture' => 'Gai Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout erabiltzean, Nyture gaiaren ordainketa-urratsen atala erakutsi.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Bezeroei dendako administratzaileak eskuz sortutako edo ordainketa-prozesuan osatu ez diren eskaeren ordainketak egiteko aukera ematen die.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers-en WooCommerce Checkout Manager plugina ez da Fluid Checkout-ekin bateragarria.','Company name field for billing address' => 'Fakturazio-helbiderako enpresaren izenaren eremua','Change visibility for the company name field for the billing address section on the checkout form.' => 'Aldatu ordainketa-formularioko fakturazio-helbidearen ataleko enpresaren izenaren eremuaren ikusgarritasuna.','Theme Bookshelf' => 'Gaiaren liburutegia','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout erabiltzean, Bookshelf gaiko ordainketa-urratsen atala atera.','Account password' => 'Kontuaren pasahitza','An account will be created with the information provided at checkout when completing the order.' => 'Eskaera osatzean ordainketa-prozesuan emandako informazioarekin kontu bat sortuko da.','Choose the style of the progress bar.' => 'Aukeratu aurrerapen-barraren estiloa.','Bars' => 'Tabernak','Theme Ireca' => 'Gaia Ireca','WooCommerce page layout' => 'WooCommerce orrialdearen diseinua','Force wide layout on WooCommerce pages' => 'Behartu diseinu zabala WooCommerce orrialdeetan','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Horrek bermatzen du edukiaren atala ez dela estuegia WooCommerce orrialdeetan, besteak beste, ordainketa, saskia, jasotako eskaera, ordainketa eskaera eta kontu orrialdeak.','WooCommerce Smart Coupons' => 'WooCommerce Kupoi Adimendunak','Position on checkout page' => 'Ordainketa-orrialdeko posizioa','Choose where to display the available coupons section on the checkout page.' => 'Aukeratu non erakutsi eskuragarri dauden kupoien atala ordainketa-orrialdean.','Before the progress bar' => 'Aurrerapen-barra baino lehen','After the progress bar' => 'Aurrerapen-barraren ondoren','Before coupon codes section' => 'Kupoi kodeen aurreko atala','Format phone numbers according to the rules for each country.' => 'Formatu telefono zenbakiak herrialde bakoitzaren arauen arabera.','Use precise phone number validation' => 'Erabili telefono zenbakiaren balidazio zehatza','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ezaugarri esperimentala da hau eta baliteke konfigurazio guztietan espero bezala ez funtzionatzea. Kontuz erabili.','Phone number validation types used when precise validation is enabled.' => 'Balidazio zehatza gaituta dagoenean erabiltzen diren telefono zenbakien balidazio motak.','Mobile' => 'Mugikorra','Fixed line' => 'Linea finkoa','Toll free' => 'Doako telefonoa','Or' => 'Edo','Contact' => 'Kontaktua','Multi step' => 'Urrats anitzeko','2 columns' => '2 zutabe','1 column' => 'Zutabe 1','Before checkout steps' => 'Ordainketa egin aurretiko urratsak','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;Zutabe 1&quot;</em> ordainketa-diseinua erabiltzean, aukera hau beti <em>&quot;Ordainketa-urratsak baino lehen&quot;</em> gisa ezartzen da eta mahaigaineko ikuspegiari ere aplikatzen zaio.','Position for the extra order summary section on mobile.' => 'Mugikorreko eskaera laburpen atal gehigarriaren kokapena.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;Guneko goiburuan&quot;</em> aukera goiburu distrakziorik gabekoa erabiltzean bakarrik aplikatzen da.','On the site header (requires distraction-free header)' => 'Gunearen goiburuan (distrakziorik gabeko goiburua behar du)','Initial state for the expansible order summary section on mobile.' => 'Mugikorrean zabal daitekeen eskaera laburpen atalaren hasierako egoera.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Araudi-eskakizunak direla eta, <em>zabalduta</em> gisa ezartzea gomendatzen dugu herrialde hauetan: <strong>Alemania</strong> , <strong>Austria</strong> , <strong>Suitza</strong> , <strong>Herbehereak</strong> , <strong>Polonia</strong> , <strong>Belgika</strong> eta <strong>Frantzia</strong> .','Collapsed' => 'Tolestuta','Expanded' => 'Zabalduta','Do not show' => 'Ez erakutsi','yes' => 'bai','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Bidalketa-telefonoaren eremua &quot;beharrezkoa&quot; gisa behartuta egon daiteke fakturazio-helbidearen atala bidalketa-helbidearen atalaren ondoren bistaratzen bada, eta fakturazio-telefonoaren eremua &quot;beharrezkoa&quot; gisa ezarrita badago. Hau beharrezkoa da bidalketa-helbidea fakturazio-helbidean kopiatu ahal izateko aukera hori markatuta dagoenean, bestela bezeroak ezin izango baitu ordainketa-formularioa bete.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Fakturazio-telefonoaren eremua &quot;beharrezkoa&quot; gisa behartuta egon daiteke fakturazio-helbidearen atala bidalketa-helbidearen atalaren aurretik bistaratzen bada, eta bidalketa-telefonoaren eremua &quot;beharrezkoa&quot; gisa ezarrita badago. Hau beharrezkoa da bidalketa-helbidea fakturazio-helbidean kopiatu ahal izateko aukera hori markatuta dagoenean, bestela bezeroak ezin izango du ordainketa-formularioa bete.','Settings profiles' => 'Ezarpenen profilak','Settings profile' => 'Ezarpenen profila','You do not have permission to perform this action.' => 'Ez duzu ekintza hau egiteko baimenik.','You do not have permission to activate plugins.' => 'Ez duzu pluginak aktibatzeko baimenik.','Missing plugin.' => 'Plugin falta.','Plugin activated.' => 'Plugin-a aktibatuta.','The following changes will be applied:' => 'Aldaketa hauek aplikatuko dira:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Fluid Checkout 5.0 bertsiotik aurrera, ezarpenak modu ezberdinean gordetzen dira. Aukera zaharrak datu-basean gordetzen dira oraindik, behar izanez gero aurreko bertsioetara jaitsi ahal izateko.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Zure denda 2 aste inguru daramatza ezarpen berriekin martxan, beraz, datu-basean gordetako aukera zaharrak garbitu ahal izan dituzu. Kontuan izan, garbitu ondoren, pluginaren aurreko bertsioetara jaitsi behar baduzu, ezarpen guztietarako balio lehenetsiak erabiliko dituela.','Fluid Checkout settings cleanup' => 'Fluid Checkout ezarpenen garbiketa','Delete leftover options' => 'Ezabatu soberan dauden aukerak','Help us improve Fluid Checkout' => 'Lagundu iezaguzu Fluid Checkout hobetzen','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Partekatu gune-ingurunearen txosten anonimoak Fluid Checkout-ekin laguntza azkarragoa lortzeko eta bateragarritasuna hobetzen eta eragina neurtzen laguntzeko. Ez da bezero, erabiltzaile edo datu sentikorrik sartzen. Zer partekatzen den aukera dezakezu edozein unetan Tresnen ezarpenetatik.','Enable site environment reports' => 'Gaitu gunearen ingurune txostenak','Review settings' => 'Berrikusi ezarpenak','This preview has expired. Reload the admin page to start a new preview.' => 'Aurreikuspen hau iraungi da. Kargatu berriro administrazio-orria aurreikuspen berri bat hasteko.','Preview expired' => 'Aurrebista iraungi da','Orders cannot be placed in the preview.' => 'Ezin dira eskaerak aurrebistan egin.','Logging in is not available in the preview.' => 'Saioa hastea ez dago eskuragarri aurrebistan.','Accounts cannot be created in the preview.' => 'Ezin dira kontuak sortu aurrebistan.','Requests to other sites are blocked in the preview.' => 'Beste guneetarako eskaerak blokeatuta daude aurrebistan.','Processing…' => 'Prozesatzen…','Something went wrong. Please try again.' => 'Zerbait gaizki joan da. Saiatu berriro.','Activate plugin' => 'Aktibatu plugina','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Ordainketa pakete osoa','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'PRO funtzio guztiak + gehigarri guztiak, prezio bakarra. Diseinu txantiloiak, erosketa-saskiaren eta eskaera jasotako orrialde optimizatuak, kontuen parekatzea eta askoz gehiago.','Optimized order pay page' => 'Eskaera ordainketa orri optimizatua','Express checkout buttons from supported payment methods' => 'Ordainketa-metodo onartuen ordainketa azkarraren botoiak','Delayed account creation' => 'Kontuaren sorrera atzeratua','Address autocomplete with Google Maps APIs' => 'Helbidearen osaketa automatikoa Google Maps APIekin','Multiple saved addresses with the address book' => 'Helbide-liburuan hainbat helbide gordeta','EU-VAT assistant' => 'EBko BEZ laguntzailea','Hide this section' => 'Ezkutatu atal hau','Learn more' => 'Informazio gehiago','Get early access' => 'Lortu sarbide goiztiarra','Activate add-on' => 'Aktibatu gehigarria','Get more out of your checkout journey' => 'Atera etekin handiagoa zure ordainketa-prozesuari','Test API key' => 'Probatu API gakoa','Guided setup' => 'Konfigurazio gidatua','Options' => 'Aukerak','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Konfiguratu ordainketa- <a href="%s">aukeren</a> diseinua eta diseinua.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Gaitu gonbidatuen ordainketa eta/edo berrikusi <a href="%s">bezeroen kontuen ezarpenak</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Gaitu <a href="%1$s">erosketa-saski</a> optimizatua, <a href="%2$s">eskerrak emateko</a> orria eta <a href="%3$s">eskaera ordaintzeko</a> orria.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Gaitu <a href="%s">helbideen osatze automatikoa</a> Google Maps-etik.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Gaitu gordetako helbide bat baino gehiago <a href="%s">helbide-liburuarekin</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Egiaztatu instalatuta dituzun gai edo beste plugin batzuen <a href="%s">integrazio aukerarik</a> dagoen.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Lortu laguntza azkarragoa eta lagundu iezaguzu bateragarritasuna hobetzen eta eragina neurtzen. <a href="%s">Gaitu erabileraren jarraipena</a> tresnen ezarpenetatik.','Missing settings tab.' => 'Ezarpenen fitxa falta da.','Getting started' => 'Hasteko','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Bikain! Zure ordainketa-orria Fluid Checkout-en exekutatzen ari da orain.</strong> Hona hemen hasteko urrats batzuk:','Completed' => 'Osatuta','Preview report data' => 'Txostenaren datuak aurreikustea','Send now' => 'Bidali orain','Auto-detect' => 'Detektatu automatikoki','Afrikaans' => 'Afrikaans','Albanian' => 'Albaniarra','Amharic' => 'Amharera','Arabic' => 'Arabiera','Armenian' => 'Armeniarra','Azerbaijani' => 'Azerbaijanera','Basque' => 'Euskera','Belarusian' => 'Bielorrusiarra','Bengali' => 'Bengalera','Bosnian' => 'Bosniarra','Bulgarian' => 'Bulgariera','Burmese' => 'Birmaniarra','Catalan' => 'Katalana','Chinese' => 'Txinera','Chinese (Simplified)' => 'Txinera (sinplifikatua)','Chinese (Hong Kong)' => 'Txinera (Hong Kong)','Chinese (Traditional)' => 'Txinera (Tradizionala)','Croatian' => 'Kroaziera','Czech' => 'Txekiarra','Danish' => 'Daniera','Dutch' => 'Nederlandera','English' => 'Ingelesa','English (Australian)' => 'Ingelesa (Australia)','English (Great Britain)' => 'Ingelesa (Britainia Handia)','Estonian' => 'Estoniarra','Farsi' => 'Farsi','Finnish' => 'Finlandiera','Filipino' => 'Filipinarra','French' => 'Frantsesa','French (Canadian)' => 'Frantsesa (Kanadarra)','Galician' => 'Galiziarra','Georgian' => 'Georgiarra','German' => 'Alemana','Greek' => 'Greziera','Gujarati' => 'Gujaratiarra','Hebrew' => 'Hebreera','Hindi' => 'Hindia','Hungarian' => 'Hungariarra','Icelandic' => 'Islandiarra','Indonesian' => 'Indonesiera','Italian' => 'Italiera','Japanese' => 'Japoniera','Kannada' => 'Kannada','Kazakh' => 'Kazakhstan','Khmer' => 'Khmerra','Korean' => 'Koreera','Kyrgyz' => 'Kirgiz','Lao' => 'Lao','Latvian' => 'Letoniera','Lithuanian' => 'Lituaniarra','Macedonian' => 'Mazedoniarra','Malay' => 'Malaysiarra','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mongoliera','Nepali' => 'Nepalera','Norwegian' => 'Norvegiera','Polish' => 'Poloniera','Portuguese' => 'Portugesa','Portuguese (Brazil)' => 'Portugesa (Brasil)','Portuguese (Portugal)' => 'Portugesa (Portugal)','Punjabi' => 'Punjabi','Romanian' => 'Errumaniera','Russian' => 'Errusiera','Serbian' => 'serbierarra','Sinhalese' => 'Sinhala','Slovak' => 'Eslovakiera','Slovenian' => 'Esloveniera','Spanish' => 'Gaztelania','Spanish (Latin America)' => 'Gaztelania (Latinoamerika)','Swahili' => 'Swahilia','Swedish' => 'Suediera','Tamil' => 'Tamil','Telugu' => 'Telugu','Thai' => 'Thailandiarra','Turkish' => 'Turkiarra','Ukrainian' => 'Ukrainiera','Urdu' => 'Urduera','Vietnamese' => 'Vietnamdarra','Zulu' => 'Zuluera','Google address autocomplete' => 'Google helbidearen autokonpletea','Google Places API version' => 'Google Places API bertsioa','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Aukeratu Google Places APIaren zein bertsio erabili nahi duzun. Ahalik eta azkarren Places API berrira aldatzea gomendatzen dizugu.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '&quot;Places API (Berria)&quot; erabiltzea gomendatzen dugu 2025eko martxoaren 1etik aurrera. Google-k &quot;Places API (Legacy)&quot; bertsioa Legacy egoerara eramango du, hau da, ezingo duzu zerbitzu hau API gako berrietarako gaitu eta API bertsio hori ez da gehiago erabilgarri egongo. Legacy APIa erabiltzen duten kontuek etenik gabe funtzionatzen jarrai dezakete.','(Recommended)' => '(Gomendatua)','Google API key' => 'Google API gakoa','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Itsatsi zure Google API gakoa eta erabili proba botoia webgune honetarako funtzionatzen duela baieztatzeko. Ziurtatu gakoa baliozkoa dela eta zure domeinurako baimenduta dagoela, bestela helbide eremua blokeatu egin daiteke bezeroek beren eskaerak osatzea eragotziz.','Enable Google address autocomplete' => 'Gaitu Google helbideen autoosatze-lana','Enable address autocompletion using the Google Maps APIs.' => 'Gaitu helbideen osatze automatikoa Google Maps APIak erabiliz.','Google API language' => 'Google API hizkuntza','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Hizkuntza hau erabiliko da Google Places API helbideen iradokizunak bistaratzeko eta helbideak ere automatikoki osatuko dira hizkuntza honetan.','Result types' => 'Emaitza motak','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Utzi hutsik edozein motatako emaitza onartzeko, normalean emaitza hobeak ematen baititu. <a href="%s" target="_blank">Ikusi dokumentazioa xehetasun gehiago lortzeko</a> .<br> Hautatu gehienez 5 helbide-bilaketa-emaitza mota helbidea automatikoki osatzeko eremuetan itzultzeko.<br> Bisitatu Google Maps-en dokumentazioa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">onartzen diren motak</a> ezagutzeko.','Result types (Legacy API)' => 'Emaitza motak (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Zein helbide-bilaketa-emaitza mota itzuli behar diren Places APIa (Legacy) erabiltzean.<br> Bisitatu Legacy Google Places APIaren dokumentazioa <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">onartutako motak</a> ezagutzeko.','Company fields' => 'Enpresaren eremuak','Enable autocomplete for the company name if available' => 'Gaitu enpresaren izenaren autoosatze funtzioa eskuragarri badago','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Gaitu enpresaren eremuaren osatze automatikoa enpresaren izenaren informazioarekin Google Maps APIetatik itzultzen denean.','Business search' => 'Negozioen bilaketa','Enable search for businesses in the company field' => 'Gaitu enpresak bilatzeko aukera enpresaren eremuan','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Gaitu enpresa batekin lotutako helbideen iradokizuna enpresaren eremuan idazterakoan, eta bete automatikoki helbide-eremu guztiak iradokizunetatik enpresa bat hautatzen denean.','Company result types' => 'Enpresaren emaitza motak','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Hautatu gehienez 5 helbide-bilaketa-emaitza mota enpresaren eremuak automatikoki betetzean itzultzeko.<br> Gomendatutako balioa <code>establishment</code> da, negozio mota gehienak barne hartzen dituena.<br> Utzi hutsik edozein motatako emaitza onartzeko, negozioekin zerikusirik ez duten emaitzak barne.<br> Bisitatu Google Maps-en dokumentazioa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">onartzen diren motak</a> ezagutzeko.','Google logo' => 'Google-ren logotipoa','Show text and logo "Powered by Google"' => 'Erakutsi &quot;Google-k bultzatuta&quot; testua eta logotipoa','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Markatuta dagoenean, &quot;Powered by Google&quot; testua eta logotipoa helbidea automatikoki osatzeko iradokizunen koadroaren behealdean agertuko dira.','Brasil API address autocomplete' => 'Brasilgo API helbidearen autoosagarria','Brasil API' => 'Brasilgo APIa','Enable Brasil API address autocomplete for CEP fields' => 'Gaitu Brasilgo API helbideen autoosatze CEP eremuetarako','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Erabili Brasil APIa helbideak berreskuratu eta automatikoki betetzeko CEP/Posta kodea eremua erabiliz. Brasilgo helbideetarako bakarrik da garrantzitsua.','API version' => 'API bertsioa','Choose which version of the Brasil API CEP method to use.' => 'Aukeratu Brasil API CEP metodoaren zein bertsio erabili nahi duzun.','Address book migration' => 'Helbide-liburuaren migrazioa','WooCommerce addresses' => 'WooCommerce helbideak','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopiatu WooCommerce-ko bidalketa eta fakturazio helbideak bezeroen helbide-liburuan.','Enable the address book feature' => 'Gaitu helbide-liburuaren funtzioa','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Bezeroei hainbat helbide gordetzeko aukera eman eta bidalketa eta fakturaziorako erabiliko den helbide lehenetsia definitzeko.','Address labels' => 'Helbide-etiketak','Allow customers to add a custom label for each address' => 'Utzi bezeroei helbide bakoitzerako etiketa pertsonalizatu bat gehitzen','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Helbide-etiketek bezeroei errazago bereizten laguntzen diete gordetako helbideak (adibidez: &quot;Amaren Etxea&quot;). Helbide-etiketak bezeroentzat pribatuak dira, eta ez dira eskaeraren xehetasunen orrialdean edo fakturetan bistaratuko edo inprimatuko.','Display layout' => 'Pantailaren diseinua','Choose how saved addresses are displayed at checkout and on the cart.' => 'Aukeratu gordetako helbideak nola bistaratzen diren ordainketa-prozesuan eta erosketa-saskian.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Ordainketa-prozesuan eta erosketa-saskian aplikatzen da. Kontuaren orrialdean gordetako helbideek beti erabiltzen dute txartelen diseinua.','Address cards' => 'Helbide-txartelak','Address list' => 'Helbide zerrenda','Dropdown field' => 'Goitibeherako eremua','Address search' => 'Helbide bilaketa','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Erakutsi helbide-bilaketa iragazkia frontend-ean bezeroak gordetako helbide kopuru hori gutxienez duenean.','Not used when display layout is set to dropdown field.' => 'Ez da erabiltzen pantailaren diseinua goitibeherako eremu gisa ezarrita dagoenean.','Addresses' => 'Helbideak','Enable cart page optimizations to see more options' => 'Gaitu saskiaren orrialdeen optimizazioak aukera gehiago ikusteko','Sticky order summary' => 'Eskaera itsaskorraren laburpena','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Hautatu saskiaren orrialdean kupoi-kodeen atala bistaratzeko posizioa. AJAX saskia gaituta dagoenean eta WooCommerce ezarpenetan kupoi-kodeen erabilera gaituta badago soilik aplikagarria.','Layout of cross-sell' => 'Salmenta gurutzatuaren diseinua','Cross-sells displayed' => 'Salmenta gurutzatuak bistaratu dira','Items' => 'Elementuak','Cart page optimization' => 'Saskiaren orrialdearen optimizazioa','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Eman iezaiozu zure erosketa-saskiari ordainketa-prozesuaren diseinu argi eta bihurketetan oinarritutako bera.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Erosketa-prozesu koherentea izan dadin, erosketa-saskiaren diseinua ordainketa-orriarekin bat etorri.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Mantendu saskia beti eguneratuta atzeko planoan, ez da orrialde osoa berriro kargatuko kantitateak aldatzen direnean.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Jarri kupoi kodeak, bidalketa gastuak eta salmenta gurutzatuak gehien bihurtzen duten lekuan.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Mantendu eskaeraren laburpena ikusgai behera egiten duzun bitartean, eta gehitu konfiantza ikurrak erosleek lasaitasuna behar duten lekuetan.','Columns' => 'Zutabeak','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Ordainketa-urratsen, eskaeraren laburpenaren eta beste atal batzuen estilo orokorrak. Beste ordainketa-orrialdeetan, saskian, eskerrak emateko orrietan (eskaera jasota) eta eskaera ikusteko orrietan aplikatzen da.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Zatitu&quot;</em> diseinu txantiloiarekin <em>&quot;1 zutabe&quot;</em> diseinua erabiltzean, eskuineko zutabea bakarrik erakusten da orriaren alboko barrako widgetaren eremua aktibo badago (Ordainketa alboko barra, Saskiaren alboko barra edo Jasotako eskaeraren alboko barra). Bestela, orria zutabe bakarrean geratzen da, zatitutako estiloekin.','Split column background' => 'Zutabe zatituaren atzeko planoa','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Aukeratu bigarren mailako diseinu zatituaren zutabearen atzeko planoaren kolorea. Utzi hutsik eskaeraren laburpenaren atzeko planoaren kolorea erabiltzeko.','Page templates' => 'Orrialde txantiloiak','Checkout template' => 'Ordainketa-txantiloia','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Ordainketa-unean distrakzio gutxiago izateko gomendagarria. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Irakurri saskia uzteari buruzko ikerketa</a> .','Sticky progress bar' => 'Aurrerapen-barra itsaskorra','Progress bar style' => 'Aurrerapen-barraren estiloa','Order totals' => 'Eskaeren guztirakoak','Background color' => 'Atzeko planoaren kolorea','Action link' => 'Ekintza-esteka','Mobile order summary' => 'Mugikorreko eskaeraren laburpena','Mobile initial state' => 'Mugikorreko hasierako egoera','Enable editing cart items at checkout' => 'Gaitu saskiko elementuak editatzea ordainketa-prozesuan','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Utzi bezeroei produktuen kantitateak aldatzen edo elementuak zuzenean ordainketa-orrialdean kentzen.','Cart item errors' => 'Saskiko elementuen erroreak','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Kupoi-kodea ordainketa-orrietan edo erosketa-saskiko orrialdeetan atal bereizi gisa bistaratzen denean bakarrik aplikagarria, eta kupoi-kodeen erabilera WooCommerce-ren ezarpenetan gaituta badago.','Coupon codes position' => 'Kupoi kodeen posizioa','Apply coupon button' => 'Aplikatu kupoi botoia','Select style of the "apply coupon" button.' => 'Hautatu &quot;kupoia aplikatu&quot; botoiaren estiloa.','Address line 2' => 'Helbidearen 2. lerroa','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ezarpen hau Ordainketa eta Tokiko bilketa atalen artean partekatzen da. Tokiko bilketa atalean, Bidalketa/Jasotze hautatzailea bidalketa metodoaren atalean (helbidearen aurretik) edo atal bereizi gisa (ondoren) agertzen den ere erabakitzen du.','Customer accounts' => 'Bezeroen kontuak','Guest checkout' => 'Gonbidatuen check-out-a','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Gonbidatuen ordainketa, saioa hasteko eta kontua sortzeko aukerak WooCommerce kontuen ezarpenen orrialdetik. Hemen kudeatzen dira zure erosotasunerako, eta beraz, balio desberdinak erabil ditzakezu ezarpen-profil bakoitzeko.','Allow customers to checkout without an account' => 'Bezeroei konturik gabe ordainketa egiteko aukera eman','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Gomendagarria da</strong> bezeroei ez eskatzeko kontu bat sortzeko edo saioa hasteko ordainketa-prozesuan, horrek bihurketa-tasak jaitsi baititzake.','When disabled, customers must log in or create an account to complete the purchase.' => 'Desgaituta dagoenean, bezeroek saioa hasi edo kontu bat sortu behar dute erosketa osatzeko.','Login at checkout' => 'Saioa hasi ordainketa-prozesuan','Enable log-in during checkout' => 'Gaitu saioa hasteko aukera ordainketa-prozesuan','Show a link for returning customers to log in from the checkout page.' => 'Erakutsi bezero errepikakorrei ordainketa-orrialdetik saioa hasteko esteka bat.','Account creation' => 'Kontuaren sorrera','Allow customers to create an account during checkout' => 'Utzi bezeroei kontu bat sortzen ordainketa-prozesuan','Customers can create an account before placing their order.' => 'Bezeroek kontu bat sor dezakete eskaera egin aurretik.','Allow customers to create an account from the My account page' => 'Bezeroei Nire kontua orrialdetik kontu bat sortzeko aukera eman','Customers can register a new account from the My account page.' => 'Bezeroek kontu berri bat erregistratu dezakete Nire kontua orrialdetik.','Username' => 'Erabiltzaile-izena','Generate from customer\'s name' => 'Bezeroaren izenetik sortu','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Gomendagarria da</strong> bezeroei ez eskatzeko erabiltzaile-izen bat aukeratzeko ordainketa-prozesuan, horrek bihurketa-tasak jaitsi baititzake.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Erabiltzaile-izena bezeroaren izenetik edo, izenik erabili ezin denean, helbide elektronikotik sortzen da.','Password' => 'Pasahitza','Send password setup link' => 'Bidali pasahitza konfiguratzeko esteka','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Gomendagarria da</strong> bezeroei ez eskatzeko pasahitzik ordainketa-prozesuan, horrek bihurketa-tasak jaitsi baititzake.','Customers receive an email to create their password securely.' => 'Bezeroek mezu elektroniko bat jasotzen dute pasahitza modu seguruan sortzeko.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Utzi erregistratutako bezeroei saioa hasi gabe ordainketa burutzen eta eskaera beren kontuarekin lotzen harremanetarako datuak bat datozenean.','Existing account message' => 'Kontuaren mezua','Let customers create an account after placing their order, from the thank you page.' => 'Utzi bezeroei kontu bat sortzen eskaera egin ondoren, eskerrak emateko orrialdetik.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Atal honetako aukerak eskuragarri daude gonbidatuen ordainketa eta kontuen parekatzea gaituta daudenean. Gaitu goiko bi funtzioak kontua sortzea atzeratuta konfiguratzeko.','Enable delayed account creation' => 'Gaitu kontua atzeratzeko sorrera','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Gaitu kontua atzeratzeko sorrera gonbidatuen ordainketa eta kontuaren parekatzea gaituta daudenean.','Section position' => 'Atalaren posizioa','Before customer details section' => 'Bezeroaren xehetasunen aurreko atala','After customer details section' => 'Bezeroaren xehetasunen atalaren ondoren','Account creation benefits' => 'Kontua sortzeko abantailak','Leaving the field empty will display the default text.' => 'Eremua hutsik uzten baduzu, testu lehenetsia bistaratuko da.','Inline buttons' => 'Lerroko botoiak','Required fields' => 'Beharrezko eremuak','Enable gift message fields at checkout' => 'Gaitu opari-mezuen eremuak ordainketa-prozesuan','Expanded gift message' => 'Opari-mezu zabaldua','Display gift message field always expanded' => 'Opari mezuaren eremua beti zabalduta','Gift message in order details' => 'Opariaren mezua eskaeraren xehetasunetan','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Momentuz ez dago integraziorik eskuragarri atal honetan. Plugin eta gai bakoitzari lotutako aukerak hemen agertuko dira plugin edo gai hori aktibatuta dagoenean bakarrik.','Phone fields' => 'Telefono eremuak','Field visibility' => 'Zelaiko ikusgarritasuna','Field position' => 'Zelaiko posizioa','Phone country code & validation' => 'Telefonoaren herrialde kodea eta baliozkotzea','Country' => 'Herrialdea','Enable country on phone fields' => 'Gaitu herrialdea telefono eremuetan','Filter countries for shipping or billing' => 'Iragazi herrialdeak bidalketa edo fakturaziorako','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Mugatu telefono-eremu bakoitzeko herrialde-hautatzailea zure dendan bidalketa edo fakturaziorako baimendutako herrialdeetara.','Validation' => 'Balidazioa','Enable simple validation based on country rules' => 'Gaitu balidazio sinplea herrialdeko arauetan oinarrituta','Checks that the phone number is valid for the selected country, including country code and length.' => 'Hautatutako herrialderako telefono zenbakia baliozkoa dela egiaztatzen du, herrialde kodea eta luzera barne.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Hautatutako herrialderako baliozko mugikor, finko edo beste mota bateko telefonoa dela egiaztatuko da zorrotzago. Baliozko zenbaki batzuk baztertu daitezke.','Validation types' => 'Balidazio motak','Placeholders' => 'Leku-markatzaileak','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Momentuz ez dago kudeatzeko lizentzia-giltzarik. Lizentzia-giltzak hemen agertuko dira Fluid Checkout plugin edo gehigarri lizentziadun bat aktibo dagoenean.','Default delivery type' => 'Bidalketa mota lehenetsia','Choose which delivery type will be selected by default.' => 'Aukeratu zein entrega mota hautatuko den lehenespenez.','Shipping zone fields' => 'Bidalketa-eremuaren eremuak','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Aukeratu zein eremu bistaratuko diren tokiko bilketa-bidalketa eremuaren iragazki-eremuetarako. Utzi hutsik eskuragarri dauden aukera guztiak erakusteko.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Eremu hauek tokiko bilketa-bidalketa metodoetarako iragazki gisa bistaratuko dira. Baliteke eremu batzuk ordainketa-prozesuan agertzea hemen hautatuta ez badaude ere, plugin bateragarriek behar bezala funtzionatzea eskatzen badute.','Order shipping address' => 'Eskaera bidaltzeko helbidea','Order pay page optimization' => 'Eskaera ordainketa orriaren optimizazioa','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Eman ordaindu gabeko eskaerei ordainketa-prozesuan bezala diseinu argi eta bihurketa-zentratu bera.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizatu ordainketa-orrialdearen diseinua ordainketa zain dauden eskaeretarako.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Erosketa-prozesu koherentea izan dadin, lotu eskaeraren ordainketa-esperientzia zure ordainketa-prozesuarekin.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Gehitu konfiantza-ikurrak eta txapa erosleek ordaindu aurretik lasaitasuna behar duten lekuetan.','Thank you page optimization' => 'Eskerrik asko orriaren optimizazioa','Make the thank you page and order details clearer for customers after they buy.' => 'Egin eskerrak emateko orria eta eskaeraren xehetasunak argiagoak bezeroentzat erosi ondoren.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizatu eskerrak emateko orria eta kontuaren eskaeraren xehetasunak diseinu argiago batekin.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Erakutsi eskaeraren egoeraren aurrerapena, ekintzak, deskargak eta oharrak zentzua duten lekuan.','Customize order details sections on email notifications.' => 'Pertsonalizatu eskaeraren xehetasunen atalak posta elektroniko bidezko jakinarazpenetan.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Gehitu konfiantza-ikurrak eta txapa erosleek erosketaren ondoren lasaitasuna behar duten lekuetan.','Email notifications' => 'Posta elektroniko bidezko jakinarazpenak','Enable thank you page and order details optimizations to see more options' => 'Aukera gehiago ikusteko, gaitu eskerrak emateko orriaren eta eskaeraren xehetasunen optimizazioak','Use wide layout on thank you page' => 'Erabili diseinu zabala eskerrak emateko orrialdean','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Aukera hauek eskerrak emateko orrialdean, kontu-orrietako eskaeraren xehetasunetan eta posta elektroniko bidezko jakinarazpenetan eragina dute.','Save settings' => 'Gorde ezarpenak','Docs' => 'Dokumentuak','Cart' => 'Saskia','Thank you' => 'Eskerrik asko','Address autocomplete' => 'Helbidearen osatze automatikoa','Trust badges' => 'Konfiantza txapa','You do not have permission to save these settings.' => 'Ez duzu baimenik ezarpen hauek gordetzeko.','Invalid save request.' => 'Gordetzeko eskaera baliogabea.','Your settings have been saved.' => 'Zure ezarpenak gorde dira.','Saving...' => 'Gordetzen...','Settings could not be saved. Please try again.' => 'Ezin izan dira ezarpenak gorde. Saiatu berriro.','Dismiss notice' => 'Baztertu oharra','Open settings menu' => 'Ireki ezarpenen menua','Close settings menu' => 'Itxi ezarpenen menua','Preview' => 'Aurreikuspena','Expand preview' => 'Zabaldu aurrebista','Collapse preview' => 'Tolestu aurrebista','Show header and footer' => 'Erakutsi goiburua eta oina','Hide header and footer' => 'Ezkutatu goiburua eta orri-oina','Page preview' => 'Orriaren aurrebista','Preview viewport' => 'Aurreikusi ikuspegi-leihoa','Tablet' => 'Tableta','Desktop' => 'Mahaigaina','Preview width' => 'Aurrebistaren zabalera','Decrease width' => 'Txikitu zabalera','Preview width in pixels' => 'Aurrebistaren zabalera pixeletan','Increase width' => 'Handitu zabalera','Preview as' => 'Aurreikusi honela','Guest' => 'Gonbidatua','Logged in' => 'Saioa hasita','Preview page' => 'Aurreikuspen orria','Expand preview for a closer look' => 'Zabaldu aurrebista ikuspegi hurbilago bat lortzeko','Available with %s.' => '%s-rekin eskuragarri.','Turn them on' => 'Piztu itzazu.','Optimizations for this page are turned off. %s to preview the page.' => 'Orrialde honen optimizazioak desaktibatuta daude. %s orria aurreikusteko.','%s preview' => '%s aurrebista','Isolated session · nothing is saved' => 'Saio isolatua · ez da ezer gorde','Usage tracking' => 'Erabileraren jarraipena','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Bidali guneko inguruneari buruzko txosten ez-sentikorrak Fluid Checkout-ek bateragarritasuna hobetzen laguntzeko. Txostenak ez dira bidaltzen beheko aukeretan gaituta egon arte.','Send usage tracking reports to Fluid Checkout' => 'Bidali erabileraren jarraipen-txostenak Fluid Checkout-era','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Txosten hauek zure gunearen bateragarritasuna eta laguntza hobetzen laguntzen digute eta gaituta daudenean astero bidaltzen dira.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Ez da bezero, administratzaile, erabiltzaile edo bestelako datu sentikorrik sartzen txostenetan.','Basic environment info' => 'Ingurumenari buruzko oinarrizko informazioa','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, gai eta pluginen zerrenden datuak. Txostenak gaituta daudenean beti sartzen dira. Zure webgunea exekutatzen ari den ingurunea ulertzen laguntzen digu.','Plugin settings' => 'Pluginaren ezarpenak','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Fluid Checkout pluginaren ezarpenak bidaltzen ditu laguntza-eskaerekin laguntzeko eta gure pluginak nola erabiltzen ari zaren ulertzen laguntzen digu.','Coming soon' => 'Laster','Sales metrics' => 'Salmenta-neurriak','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Fluid Checkout instalatu baino urtebete lehenagoko hileko eskaeren kopurua eta gaur arteko salmenta guztiak. Gure pluginak instalatuta diru gehiago irabazten ari zaren ulertzen laguntzen digu. Ez da inoiz bezero edo erabiltzaileen daturik bidaltzen.','Utilities' => 'Zerbitzuak','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Erabili <code>TomSelect</code> goitibeherako osagaiak <code>select2</code> ren ordez','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect goitibeherako hautaketa osagai sinpleagoa da, Select2 baino errore gutxiago izateko joera duena, funtzionalitate bera eskaintzen duen arren.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Plugin honek optimizatutako orrialdeetan, formulario-eremuen barruko letra-tamaina 16px-tan ezartzen du, gailu txikietan formulario-eremuekin elkarreraginean automatikoki zooma ez egiteko.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari eta beste arakatzaile batzuek automatikoki handitu dezakete gailu mugikorretan testua errazago irakurtzeko, 16px baino txikiagoa denean letra-tamaina.','Enable script processing tracking on the browser console.' => 'Gaitu script-en prozesamenduaren jarraipena arakatzailearen kontsolan.','Unminified assets' => 'Aktibo txikitu gabeak','Google Maps scripts' => 'Google Maps-eko gidoiak','Do not remove duplicate Google Maps scripts' => 'Ez kendu Google Maps-eko script bikoiztuak','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Gaituta dagoenean, Google Maps-eko script bikoiztuak EZ dira kenduko, eta horrek akatsak eta errendimendu arazoak sor ditzake. Aukera hau arazoak konpontzen ari zarenean bakarrik erabili.','Widget areas' => 'Widget eremuak','Last step on mobile' => 'Azken urratsa mugikorrean','Display widgets only at last step on mobile' => 'Widgetak mugikorreko azken urratsean bakarrik erakutsi','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Erakutsi ordainketa-fidagarritasun txapa widgetak gailu mugikorretan azken ordainketa-urratsa ikusten denean bakarrik','Standard' => 'Estandarra','VAT number field' => 'BEZ zenbakiaren eremua','Add a VAT number field to the billing form.' => 'Gehitu BEZ zenbakiaren eremu bat fakturazio-formularioan.','Field label' => 'Eremuaren etiketa','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Ezarri BEZ zenbakiaren eremuaren etiketa (hau da, BEZ zenbakia). Hizkuntza anitzeko webguneetan, hobe da eremu hau hutsik uztea eta jatorrizko katea itzultzea.','VAT Number' => 'BEZ zenbakia','EU-VAT' => 'EBko BEZa','Enable the VAT number field to see more options' => 'Gaitu BEZ zenbakiaren eremua aukera gehiago ikusteko','VAT validation' => 'BEZaren balidazioa','Validate VAT number field for EU-VAT during checkout' => 'Balioztatu BEZ zenbakiaren eremua EBko BEZerako ordainketa-prozesuan','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Emandako BEZ zenbakia Europako VIES datu-basean (BEZ Informazioa Trukatzeko Sistema) erregistratutako BEZ zenbaki baliozkoa den egiaztatzen du.','Shop VAT number' => 'Dendako BEZ zenbakia','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'EBko BEZaren balidazioa eskatzeko erabiltzen den dendaren BEZ zenbakia, eta fakturetan inprimatuta agertzen dena.<br> <strong>Zure dendako BEZ zenbakia gehitzea gomendatzen dizugu</strong> , bestela VIES kontsultaren emaitzak kontabilitate helburuetarako baliozkoak ez izatea gerta baitaiteke.<br> Alegia.: <code>ATU99999999</code> edo <code>EE999999999</code> .','Reverse charge' => 'Alderantzizko karga','Apply reverse charge mechanism' => 'Alderantzizko karga mekanismoa aplikatu','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Ezarri zerga-tasa zeroan eta erakutsi &quot;Alderantzizko karga&quot; fakturetan bezeroaren BEZ zenbakia baliozkoa denean. &quot;Alderantzizko karga&quot; testu desberdina beharrezkoa izan daiteke dendaren herrialdearen arabera.','Same country' => 'Herrialde bera.','Apply reverse charge mechanism for transactions in the shop country:' => 'Aplikatu alderantzizko kargaren mekanismoa dendaren herrialdeko transakzioetarako:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Dendaren herrialde bereko enpresen arteko transakzioetarako alderantzizko kargaren mekanismoa aplikatzea ahalbidetzen du.','Reverse charge exceptions' => 'Alderantzizko kargaren salbuespenak','Select additional countries to skip applying the reverse charge mechanism.' => 'Hautatu alderantzizko karga-mekanismoa aplikatzea saihesteko beste herrialde batzuk.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Herrialde hauetatik egindako eskaerei zergak kobratuko zaizkie, nahiz eta BEZ zenbaki balioduna eman.','Reverse charge label on invoices' => 'Fakturetan alderantzizko kargaren etiketa','Set the label of "reverse charge" on the checkout page and order details.' => 'Ezarri &quot;alderantzizko karga&quot; etiketa ordainketa-orrian eta eskaeraren xehetasunetan.','Reverse charge text on invoices' => 'Fakturetan alderantzizko kargaren testua','Set the label of "reverse charge" text on invoices.' => 'Ezarri &quot;alderantzizko karga&quot; testuaren etiketa fakturetan.','Tax to be paid on reverse charge basis' => 'Alderantzizko kargaren arabera ordaindu beharreko zerga','Company name' => 'Enpresaren izena','Autocomplete company name from VAT number' => 'Osatu automatikoki enpresaren izena BEZ zenbakitik','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Bete fakturazio-enpresaren izena bezeroak emandako BEZ zenbaki baliodunean oinarrituta.','Company name editing' => 'Enpresaren izena editatzea','Allow editing of auto-filled company name' => 'Baimendu automatikoki betetako enpresaren izena editatzea','When enabled, customers can change the company name associated with the provided VAT number.' => 'Gaituta dagoenean, bezeroek emandako BEZ zenbakiarekin lotutako enpresaren izena alda dezakete.','EU-VAT for digital goods' => 'EBko BEZa ondasun digitalen kasuan','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015eko urtarrilaren 1etik aurrera, ondasun digitalei buruzko EBko BEZ araudian aldaketak egin dira, B2C transakzioei soilik eraginez. Ondasun digitalen BEZa bezeroaren kokapenaren arabera kalkulatu behar da, eta horren frogak bildu behar dira (IP helbidea eta fakturazio helbidea).','Tax classes for digital goods' => 'Ondasun digitalen zerga-klaseak','Select some tax classes' => 'Hautatu zerga-klase batzuk','Location evidence' => 'Kokapenaren frogak','Collect customer\'s location evidence' => 'Bezeroaren kokapenaren frogak bildu','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP helbidea gordetzen du eta bezeroaren fakturazio-helbidearekin alderatzen du. Bezeroek fakturazio-helbidea berretsi behar dute ordainketa-orrialdean kontrol-lauki bat markatuz, fakturazio-helbideko herrialdea eta IP helbidea bat ez badatoz.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Aukera hau Fluid Checkout-en kudeatzen da. <a href="%s">Aldatu Bezeroen kontuen ezarpenetan</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Aukera hau Fluid Checkout-en kudeatzen da. Aldatu Fluid Checkout &gt; Bezeroen kontuak atalean.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Aukera hau Fluid Checkout-en kudeatzen da. Fluid Checkout aktibatuta dagoenean, bidalketa-helmuga beti &quot;Bezeroaren bidalketa-helbide lehenetsia&quot; gisa ezartzen da. Bezeroek bidalketa- eta fakturazio-helbide desberdinak eman ditzakete ordainketa-prozesuan.<br><br> <a href="%s">Fluid Checkout ezarpenetan</a> dago eskuragarri fakturazio-helbide lehenetsia bidalketa-helbide berdina izateko aukera.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Aukera hau Fluid Checkout-en kudeatzen da. Fluid Checkout aktibatuta dagoenean, bidalketa-helmuga beti &quot;Bezeroaren bidalketa-helbide lehenetsia&quot; gisa ezartzen da. Bezeroek bidalketa- eta fakturazio-helbide desberdinak eman ditzakete ordainketa-prozesuan.<br><br> Fakturazio-helbide lehenetsia bidalketa-helbide berdina izan dadin ezartzeko aukera WooCommerce &gt; Ezarpenak &gt; Fluid Checkout atalean dago eskuragarri.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ezarpen hauek WP Admin &gt; Fluid Checkout &gt; Ezarpenak atalera mugitu dira.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'WooCommerce ezarpenen fitxa hau zaharkituta dago eta Fluid Checkout 6.0 bertsioan kenduko da.','Go to settings page' => 'Joan ezarpenen orrialdera','Hide this tab permanently' => 'Ezkutatu fitxa hau betiko','Site report preview' => 'Gunearen txostenaren aurrebista','This is the data that would be included in the next site environment report based on your current settings.' => 'Hauek dira zure uneko ezarpenen arabera hurrengo gunearen ingurune-txostenean sartuko liratekeen datuak.','Loading report preview...' => 'Txostenaren aurrebista kargatzen...','Could not load the site report preview. Try again.' => 'Ezin izan da gunearen txostenaren aurrebista kargatu. Saiatu berriro.','Could not send the site report. Try again.' => 'Ezin izan da gunearen txostena bidali. Saiatu berriro.','Site report sent successfully.' => 'Gunearen txostena behar bezala bidali da.','Enable and send now' => 'Gaitu eta bidali orain','Close' => 'Itxi','A site report request is already in progress. Try again in a moment.' => 'Gunearen txosten eskaera bat martxan dago dagoeneko. Saiatu berriro une batean.','Site environment reporting is disabled.' => 'Gunearen ingurunearen txostenak desgaituta daude.','No site report data is available to send.' => 'Ez dago gunearen txostenaren daturik bidaltzeko eskuragarri.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Gune honetako domeinuak ezin ditu ingurumen-txostenak bidali (tokiko edo garapen-domeinuak baztertuta daude).','A site report was sent recently. Try again later.' => 'Gunearen txosten bat bidali da duela gutxi. Saiatu berriro geroago.','The site report could not be sent. Try again later.' => 'Ezin izan da gunearen txostena bidali. Saiatu berriro geroago.','Site environment reporting is not available.' => 'Gunearen ingurunearen txostenak ez daude eskuragarri.','No site report data is available for the selected settings.' => 'Ez dago hautatutako ezarpenetarako gunearen txostenaren daturik eskuragarri.','You are not allowed to manage site reports.' => 'Ez duzu baimenik guneko txostenak kudeatzeko.','PRO feature' => 'PRO funtzioa','Other plugins' => 'Beste plugin batzuk','Get only this add-on &mdash; %s' => 'Eskuratu gehigarri hau bakarrik — %s','Install add-on' => 'Instalatu gehigarria','Upgrade to PRO &mdash; %s' => 'Eguneratu PROra — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Lortu %2$s</a> aukera hauek desblokeatzeko.','Add-on' => 'Gehigarria','View documentation' => 'Ikusi dokumentazioa','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Eskaerek WordPress erabiltzaile saioa hasita behar dute. Uneko erabiltzailearen datuak erabiltzeko, ez erabili user_id, edo beste kontu bat helburu gisa erabili deitzaileak erabiltzaile hori edita dezakeenean (edit_user gaitasuna). Autentifikatu gabeko eskaerek fc_api_forbidden itzultzen dute. Baliogabeko user_id batek fc_api_user_not_found itzultzen du.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 { &quot;data&quot;: { ... } }-rekin kudeatzaileak karga bat itzultzen duenean.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 { &quot;success&quot;: true } balioarekin, kargarik ez dagoenean (adibidez, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Hutsegiteek WordPress REST errore JSON itzultzen dute WP_Error-etik (kodea, mezua, data.status). Wire kodeek fc_api_* aurrizkia erabiltzen dute.','Forbidden access.' => 'Sarbidea debekatuta.','Target user was not found.' => 'Helburuko erabiltzailea ez da aurkitu.','This feature is not available.' => 'Ezaugarri hau ez dago erabilgarri.','A required address field is missing.' => 'Beharrezko helbide-eremu bat falta da.','Postcode or ZIP is invalid.' => 'Posta kodea edo ZIP kodea baliogabea da.','Phone number is invalid.' => 'Telefono zenbakia baliogabea da.','State or county is invalid.' => 'Estatua edo konderria baliogabea da.','Country is invalid or has no address fields.' => 'Herrialdea baliogabea da edo ez du helbide-eremurik.','The request could not be processed.' => 'Eskaera ezin izan da prozesatu.','Back to previous step' => 'Aurreko urratsera itzuli','Skip to settings' => 'Joan ezarpenetara','Start over and return to the first guided setup step' => 'Hasi berriro eta itzuli lehenengo konfigurazio gidatuko urratsera','Start over' => 'Berriro hasi','Please complete all sub-steps before continuing.' => 'Jarraitu aurretik, jarraitu azpi-urrats guztiak.','Expand' => 'Zabaldu','Collapse' => 'Tolestu','Skip' => 'Saltatu','Mark as complete' => 'Markatu osatutzat','Mark as incomplete' => 'Markatu osatugabe gisa','View full-size image: %s' => 'Ikusi irudi osoa: %s','Full-size setup guide image' => 'Tamaina osoko konfigurazio-gidaren irudia','Close image' => 'Itxi irudia','Fluid Checkout Guided Setup' => 'Fluidoen egiaztapenaren konfigurazio gidatua','Welcome' => 'Ongi etorri','Explore your checkout' => 'Arakatu zure ordainketa-prozesua','All set' => 'Dena prest','You do not have permission to access this page.' => 'Ez duzu orrialde honetara sartzeko baimenik.','Go to step %1$d: %2$s' => 'Joan %1$d urratsera: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Konfigurazio gidatu honek Fluid Checkout-ekin ohitzen lagunduko dizu. Jarraian datozen urratsak oraingoz leku-markatzaileak dira.','Continue to the next step when you are ready.' => 'Jarraitu hurrengo urratsera prest zaudenean.','Open your store checkout to see Fluid Checkout in action.' => 'Ireki zure dendako kutxa Fluid Checkout martxan ikusteko.','View checkout page' => 'Ikusi ordainketa-orria','You can return to Fluid Checkout settings to continue configuring your store.' => 'Fluid Checkout ezarpenetara itzul zaitezke zure denda konfiguratzen jarraitzeko.','Review checkout and cart settings' => 'Berrikusi ordainketa eta saskiaren ezarpenak','Explore add-ons from the dashboard' => 'Arakatu gehigarriak kontrol-paneletik','Finish & go to settings' => 'Amaitu eta joan ezarpenetara','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Eguneratu fakturazio-telefonoaren eremuaren ikusgarritasun-aukera balio zaharretik WooCommerce-ren konbentzioekin bat etortzeko.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Eguneratu bidalketa-telefonoaren eremuaren ikusgarritasun-aukera balio zaharretik WooCommerce-ren konbentzioekin bat etortzeko.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopiatu eskaeraren laburpenaren atzeko planoaren kolorearen ezarpena bigarren mailako zutabearen atzeko planoaren kolore aukera berrira.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteship plugina erabiltzean, hobetutako hautaketa-eremuen funtzioa beti desgaituta dago.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Eskaera egiteko posizioa beti &quot;Eskaera laburpenaren azpian&quot; gisa ezartzen da German Market erabiltzean. Plugin horrek eskaera egiteko botoia eta legezko kontrol-laukiak eskaera laburpenaren azpian bistaratzea eskatzen du.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce-rako Germanized erabiltzean, eskaera egiteko posizioa beti &quot;Eskaera laburpenaren azpian&quot; gisa ezartzen da. Plugin horrek eskaera egiteko botoia eta legezko kontrol-laukiak eskaera laburpenaren azpian bistaratzea eskatzen du.','Edit pickup locations' => 'Editatu bilketa-lekuak','Use local pickup label from WooCommerce settings' => 'Erabili WooCommerce ezarpenetatik tokiko bilketa etiketa','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Gaituta dagoenean, ordainketa-prozesuko bilketa-aukeraren etiketa WooCommerce-ko bilketa-kokapenaren ezarpenetako izenburuarekin bat dator. Desgaituta dagoenean, etiketak Fluid Checkout-eko itzulgarria den &quot;Tokiko bilketa&quot; testua erabiltzen du.','Button label for applying coupon codesApply' => 'Aplikatu','Checkout step titleContact' => 'Harremanetan jarri','Checkout step titleShipping' => 'Bidalketa','Checkout step titleBilling' => 'Fakturazioa','Checkout step titlePayment' => 'Ordainketa','Checkout substep change link labelChange' => 'Aldatu','Checkout substep save link labelSave changes' => 'Gorde aldaketak','Substep review textNone.' => 'Bat ere ez.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Ez da irudirik hautatu.','Settings sectionCart' => 'Saskia','Settings sectionOrder pay' => 'Ordainketa agindu','Settings sectionThank you' => 'Eskerrik asko','Settings section titleIntegrations' => 'Integrazioak','Settings section titleLicense keys' => 'Lizentzia-gakoak','Captcha positionBefore place order section' => 'Eskaera egin aurretik','Captcha positionBefore place order button' => 'Eskaera egin aurretik botoia','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Itxi','Log in link label at checkout contact stepLog in' => 'Hasi saioa','Log in separator label at for when guest checkout is disabledOr continue below' => 'Edo jarraitu behean','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Edo gonbidatu gisa jarraitu','Clear image selection on admin pages.Remove image' => 'Kendu irudia','shipping packagesShipping %d' => 'Bidalketa %d','shipping packagesShipping' => 'Bidalketa','Used as fallback for "Proceed to next step" button labelnext step' => 'hurrengo urratsa','Substep review checkbox valueYes' => 'Bai','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Joan','Dummy customer last name in the admin previewDoe' => 'Eme','Dummy customer company in the admin previewExample Company' => 'Adibide Enpresa','Dummy customer street address in the admin preview123 Main Street' => 'Kale Nagusia 123','Dummy customer city in the admin previewAnytown' => 'Edozein herri','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Mesedez, utzi paketea ate aurrean.','Dummy product name in the admin previewBeanie' => 'Txanoa','Dummy product name in the admin previewCap' => 'Txapel','Dummy product name in the admin previewT-Shirt' => 'Kamiseta','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Zure eskaera jaso dugu eta bidaltzen denean eguneratze bat bidaliko dizugu.','Dummy download in the admin previewUser guide' => 'Erabiltzailearen gida','Google Places API versionsPlaces API (New)' => 'Lekuen APIa (Berria)','Google Places API versionsPlaces API (Legacy)' => 'Lekuen APIa (Legatua)','Brasil API versionsVersion 1' => '1. bertsioa','Brasil API versionsVersion 2' => '2. bertsioa','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Hurrengoan azkarrago ordaindu ✔ Kudeatu zure ordainketa-lehentasunak ✔ Ikusi eskaeraren egoera eta historia','VAT number field visibilityHidden' => 'Ezkutatuta','VAT number field visibilityOptional' => 'Aukerakoa','VAT number field visibilityRequired' => 'Beharrezkoa','Delivery typeShipping to address' => 'Helbidera bidalketa','Delivery typeLocal pickup' => 'Tokiko bilketa',] ];